// Types mirroring the data contract in CLAUDE.md. The files are generated by
// model/export_web_data.py; these types must follow them, never the other way round.
import type { Feature, FeatureCollection, Polygon } from 'geojson';

export type ParcelSet = 'train' | 'predict';
/** How the yield labels of a municipality were recorded; selects the interval width. */
export type LabelRegime = 'measured' | 'rounded';

export interface LocalizedLabel {
  es: string;
  en?: string;
}

export interface ModelMeta {
  generatedOn: string;
  source: string;
  target: string;
  units: string;
  season: string;
  nTrain: number;
  nPredict: number;
}

export interface Ensemble {
  weightA: number;
  weightB: number;
  clip: [number, number];
}

export interface ModelAFeature {
  name: string;
  label: LocalizedLabel;
  mean: number;
  sd: number;
  coef: number;
  min: number;
  max: number;
  fillValue?: number;
}

export interface ModelA {
  intercept: number;
  priorCoef: number;
  features: ModelAFeature[];
  municipalWeight: number;
  knnWeight: number;
  k: number;
  smoothing: number;
  globalMean: number;
  minDistanceKm?: number;
  ridgeAlpha?: number;
}

export interface ModelBFeature {
  name: string;
  mean: number;
  scale: number;
  coef: number;
  fillValue?: number;
}

export interface ModelB {
  intercept: number;
  features: ModelBFeature[];
  derived: { ubi_log_area: string };
  ridgeAlpha?: number;
}

export interface Intervals {
  level: number;
  halfWidth: Record<LabelRegime, number>;
  cvCoverage: Record<LabelRegime, number>;
}

export interface ValidationRepeat {
  repeticion: number;
  RMSE: number;
  MAE: number;
  R2: number;
}

export interface Validation {
  scheme?: string;
  rmse: number;
  rmseSd: number;
  mae: number;
  r2: number;
  perRepeat: ValidationRepeat[];
  baselines: {
    globalMeanRmse: number;
    municipalMeanRmse: number;
  };
}

export interface Municipality {
  name: string;
  state: string;
  nTrain: number;
  nPredict: number;
  meanYield: number;
  regime: LabelRegime;
}

interface ParcelBase {
  id: string;
  municipality: string;
  state: string;
  lon: number;
  lat: number;
  areaHa: number;
  regime: LabelRegime;
}

/** A parcel with known yield. */
export interface TrainParcel extends ParcelBase {
  set: 'train';
  actualYield: number;
  /** Out-of-fold prediction, average of the 10 CV repeats. */
  oofPrediction: number;
}

export interface Neighbor {
  id: string;
  distanceKm: number;
  weight: number;
}

export interface Prior {
  municipalMean: number;
  neighborMean: number;
  combined: number;
  municipalN: number;
  neighbors: Neighbor[];
}

/** A parcel whose yield is unknown (held by the committee). */
export interface PredictParcel extends ParcelBase {
  set: 'predict';
  /** All 19 model inputs, keyed by feature name. */
  features: Record<string, number>;
  prior: Prior;
  modelA: number;
  modelB: number;
  prediction: number;
  interval80: [number, number];
  attentionFlag: boolean;
}

export type Parcel = TrainParcel | PredictParcel;

export interface SelfTest {
  maxDiffVsPython: number;
  maxDiffVsSubmittedCsv: number;
  nChecked: number;
}

export interface ModelData {
  meta: ModelMeta;
  ensemble: Ensemble;
  modelA: ModelA;
  modelB: ModelB;
  intervals: Intervals;
  validation: Validation;
  municipalities: Municipality[];
  parcels: Parcel[];
  selfTest: SelfTest;
}

/** `[ISO date, NDVI]` */
export type CurvePoint = [string, number];

export interface Milestones {
  base: number;
  peak: number;
  amplitude: number;
  peakDoy: number;
  peakDate: string;
  sosDoy: number;
  sosDate: string;
  eosDoy: number;
  eosDate: string;
  seasonLengthDays: number;
}

export interface ParcelCurve {
  raw: CurvePoint[];
  smooth: CurvePoint[];
  milestones: Milestones;
}

export interface CurvesMeta {
  sensor: string;
  index: string;
  cloudMax: number;
  window: [string, string];
  smoothing: string;
  sosThreshold: number;
  eosThreshold: number;
}

export interface CurvesData {
  meta: CurvesMeta;
  curves: Record<string, ParcelCurve>;
}

export interface ParcelProperties {
  id: string;
  set: ParcelSet;
  municipality: string;
}

export type ParcelFeature = Feature<Polygon, ParcelProperties>;
export type ParcelCollection = FeatureCollection<Polygon, ParcelProperties>;

export const isTrain = (p: Parcel): p is TrainParcel => p.set === 'train';
export const isPredict = (p: Parcel): p is PredictParcel => p.set === 'predict';
